import{_ as e,o as r,c as l,a2 as o}from"./chunks/framework.Bx7X8BVG.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1790778157000}'),t={name:"guide/faq.md"};function d(n,a,c,i,u,h){return r(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="新装桌面端一直-初始化本地服务" tabindex="-1">新装桌面端一直“初始化本地服务”？ <a class="header-anchor" href="#新装桌面端一直-初始化本地服务" aria-label="Permalink to &quot;新装桌面端一直“初始化本地服务”？&quot;">​</a></h2><p>v1.8.0 历史小体积包没有完整运行资源，不能靠等待解决。请关闭旧程序，安装 <a href="/cloudflare-tunnel-manager/guide/desktop">v1.8.1 对应平台的包</a>。v1.8.1 本地服务就绪后才显示窗口；仍失败请检查应用数据目录的 service.log，不要重复注册。</p><h2 id="登录账号是-cloudflare-账号吗" tabindex="-1">登录账号是 Cloudflare 账号吗？ <a class="header-anchor" href="#登录账号是-cloudflare-账号吗" aria-label="Permalink to &quot;登录账号是 Cloudflare 账号吗？&quot;">​</a></h2><p>不是。面板账号保存在这次安装的 data 中。新目录首次创建管理员，已有目录登录原账号；新用户注册需管理员审核。Docker 与桌面数据不自动同步。</p><h2 id="桌面端会自动启动我本地的网站吗" tabindex="-1">桌面端会自动启动我本地的网站吗？ <a class="header-anchor" href="#桌面端会自动启动我本地的网站吗" aria-label="Permalink to &quot;桌面端会自动启动我本地的网站吗？&quot;">​</a></h2><p>不会。它启动本地管理服务和 cloudflared。要转发的网站/接口必须先启动，并让运行 Tunnel 的设备能访问。</p><h2 id="为什么桌面没有-19090-端口" tabindex="-1">为什么桌面没有 19090 端口？ <a class="header-anchor" href="#为什么桌面没有-19090-端口" aria-label="Permalink to &quot;为什么桌面没有 19090 端口？&quot;">​</a></h2><p>桌面端监听 127.0.0.1，动态选择端口，见 service.log。Docker 默认固定为 19090/19092/19093；桌面窗口就绪后自动打开正确的本地地址。</p><h2 id="docker-升级后又让注册" tabindex="-1">Docker 升级后又让注册？ <a class="header-anchor" href="#docker-升级后又让注册" aria-label="Permalink to &quot;Docker 升级后又让注册？&quot;">​</a></h2><p>通常是项目目录或 data 挂载变了，不能据此断定数据已删除。先 <code>docker inspect cf-tunnel-manager</code> 核对 <code>/app</code> 和 <code>/data</code> 的挂载源；找到旧 data、备份后再恢复。不要直接删数据。</p><h2 id="更新源-404-或地址套了两层" tabindex="-1">更新源 404 或地址套了两层？ <a class="header-anchor" href="#更新源-404-或地址套了两层" aria-label="Permalink to &quot;更新源 404 或地址套了两层？&quot;">​</a></h2><p><a href="/cloudflare-tunnel-manager/guide/update#修复更新地址重复拼接">按更新教程还原 origin</a>。Git 加速前缀与 Docker 镜像地址不能混用；清空自定义前缀并选“自动”。</p><h2 id="cloudflared-一连接就断开" tabindex="-1">cloudflared 一连接就断开？ <a class="header-anchor" href="#cloudflared-一连接就断开" aria-label="Permalink to &quot;cloudflared 一连接就断开？&quot;">​</a></h2><p>核对 Account ID/Token 权限、云端隧道是否存在、转发地址是否可达，并查看运行日志。网络不支持 UDP 时可尝试 HTTP2，不能保证切换协议一定解决线路问题。</p><h2 id="云端在线、本地离线" tabindex="-1">云端在线、本地离线？ <a class="header-anchor" href="#云端在线、本地离线" aria-label="Permalink to &quot;云端在线、本地离线？&quot;">​</a></h2><p>可能是别的设备还运行着该隧道，或本机未连上。核对本地进程、连接日志和公网真实请求，不能仅看一个状态字段。</p><h2 id="同一隧道可以运行多个副本吗" tabindex="-1">同一隧道可以运行多个副本吗？ <a class="header-anchor" href="#同一隧道可以运行多个副本吗" aria-label="Permalink to &quot;同一隧道可以运行多个副本吗？&quot;">​</a></h2><p>Cloudflare 官方支持，每隧道最多 25 个活跃副本。但副本可能分别收到请求，需要配置一致、业务服务均可达；不要把副本误用于随机切换到不同业务服务。来源：<a href="https://developers.cloudflare.com/cloudflare-one/account-limits/#cloudflare-tunnel" target="_blank" rel="noreferrer">账户限额</a>。</p><h2 id="免费-tunnel-只能-200-个请求吗" tabindex="-1">免费 Tunnel 只能 200 个请求吗？ <a class="header-anchor" href="#免费-tunnel-只能-200-个请求吗" aria-label="Permalink to &quot;免费 Tunnel 只能 200 个请求吗？&quot;">​</a></h2><p>200 个同时处理中请求是临时 Quick Tunnel 的限制，不适用于本面板通过账户创建的命名隧道。<a href="/cloudflare-tunnel-manager/guide/limits">完整限制和来源</a>。</p><h2 id="大文件上传或视频播放能保证吗" tabindex="-1">大文件上传或视频播放能保证吗？ <a class="header-anchor" href="#大文件上传或视频播放能保证吗" aria-label="Permalink to &quot;大文件上传或视频播放能保证吗？&quot;">​</a></h2><p>不能。公网 Free 套餐一次 HTTP 上传上限为 100 MB，视频/大文件分发另受条款约束。分块、超时、应用和线路也会影响结果。项目没有公布实测吞吐或大文件验收，<a href="/cloudflare-tunnel-manager/guide/limits">详见限制</a>。</p><h2 id="删除-卸载是否删除-cloudflare-配置" tabindex="-1">删除/卸载是否删除 Cloudflare 配置？ <a class="header-anchor" href="#删除-卸载是否删除-cloudflare-配置" aria-label="Permalink to &quot;删除/卸载是否删除 Cloudflare 配置？&quot;">​</a></h2><p>卸载桌面程序或 Docker 容器不等于删除 Cloudflare 云端隧道/DNS。面板删除隧道会涉及云端资源，DNS 清理行为需另外核对；先备份和确认目标。</p><h2 id="忘记-docker-管理员密码" tabindex="-1">忘记 Docker 管理员密码？ <a class="header-anchor" href="#忘记-docker-管理员密码" aria-label="Permalink to &quot;忘记 Docker 管理员密码？&quot;">​</a></h2><p>可为容器配置临时 <code>ADMIN_PASSWORD</code>，重建后用 <code>master</code>（或留空用户名）与临时密码进入，再重置正式账号。完成后移除临时入口。桌面端没有对应的图形化紧急恢复入口，不要直接套用 Docker Compose 教程。</p><h2 id="程序会把什么发给-cloudflare" tabindex="-1">程序会把什么发给 Cloudflare？ <a class="header-anchor" href="#程序会把什么发给-cloudflare" aria-label="Permalink to &quot;程序会把什么发给 Cloudflare？&quot;">​</a></h2><p>本地保存账号、配置和凭据；调用 Cloudflare API 管理隧道/DNS 时会发送相应 Token、账户和配置，业务请求通过 Tunnel 经过 Cloudflare。不能说“所有信息永远不离开本机”。日志和备份上传前必须脱敏。</p><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h2><p>在 <a href="https://github.com/lieren2012/cloudflare-tunnel-manager/issues" target="_blank" rel="noreferrer">Issues</a> 提供版本、系统/架构、操作步骤和脱敏错误日志。不要提交密码、Token、Cookie 或 data 备份。</p>',31)])])}const p=e(t,[["render",d]]);export{f as __pageData,p as default};
